const httpStatus = require('http-status');
const logger = require('../config/logger');
const { EngineDetails } = require('../models');
const ApiError = require('../utils/ApiError');
const ftp = require('basic-ftp');
const fs = require('fs');
const { FileChecker } = require('../models');
const emailService = require('./email.service');
const excelService = require('./excel.service');
const moment = require('moment');
const monthDiff = (d1, d2) => {
  let months;
  months = (d2.getFullYear() - d1.getFullYear()) * 12;
  months -= d1.getMonth();
  months += d2.getMonth();
  return months <= 0 ? 0 : months;
};
const checkWarrantySourceRecord = async (
  serialNumber,
  oem,
  engineHmr1,
  dateOfSale,
  invoiceDate,
  oemName,
  forceCheck = false
) => {
  // TODO get engineRecord for this serial number from simpson dumped table and compute warranty
  let engineHmr;
  try {
    engineHmr = parseInt(engineHmr1, 10);
  } catch (e) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Invalid HMR value ');
  }
  logger.info(`Checking warranty status for serialNumber = ${serialNumber}`);
  if (!serialNumber || !oem || !engineHmr || !dateOfSale) {
    throw new ApiError(
      httpStatus.BAD_REQUEST,
      `Invalid args to checkWarranty = Passed values => ${serialNumber}, ${oem?.name}, ${engineHmr}, ${dateOfSale}`
    );
  }
  const engineDetails = forceCheck ? { invoiceDate } : await EngineDetails.findOne({ engineSerialNumber: serialNumber });
  const emptyResponse = {
    underWarranty: null,
    serialNumber,
    invoiceNumber: null,
    hours: null,
    listNumber: null,
    dateOfSale: {
      cur: null,
      allowed: null,
      valid: false,
    },
    hmr: {
      cur: null,
      allowed: null,
      valid: false,
    },
    dateOfInvoice: {
      cur: null,
      allowed: null,
      valid: false,
    },
    oemName: oemName.name,
  };
  if (!engineDetails || engineDetails.invoiceDate === null) {
    return emptyResponse;
  }
  let maxDateOfSimpsonInvoiceToOEM;
  let maxDateOfMachineSaleByOEMToEndCustomer;
  let maxHmr;
  if (oemName.name.includes('Tractors and Farm Equipments Ltd')) {
    maxDateOfSimpsonInvoiceToOEM = 27; // in months
    maxDateOfMachineSaleByOEMToEndCustomer = 24; // in months
    maxHmr = 2000; // in hours
  } else if (oemName.name.includes('CNH Industrial (India) Private Ltd.')) {
    maxDateOfSimpsonInvoiceToOEM = 24;
    maxDateOfMachineSaleByOEMToEndCustomer = 21;
    maxHmr = 2000;
  } else if (oemName.name.includes('TEREX Equipment (P) LTD / Manitou Group')) {
    maxDateOfSimpsonInvoiceToOEM = 24;
    maxDateOfMachineSaleByOEMToEndCustomer = 18;
    maxHmr = 2000;
  } else {
    maxDateOfSimpsonInvoiceToOEM = 15;
    maxDateOfMachineSaleByOEMToEndCustomer = 12;
    maxHmr = 1500;
  }

  const dateOfSaleDiff = monthDiff(moment(dateOfSale, 'YYYY-MM-DD').toDate(), new Date());
  const dateOfInvoiceDiff = monthDiff(
    moment(
      invoiceDate || typeof engineDetails.invoiceDate === 'string'
        ? new Date(Date.parse(engineDetails.invoiceDate))
        : engineDetails.invoiceDate,
      'DD-MM-YY'
    ).toDate(),
    new Date()
  );

  if (isNaN(dateOfInvoiceDiff) || isNaN(dateOfInvoiceDiff)) {
    return emptyResponse;
  }

  let underWarranty = false;
  if (
    engineHmr <= maxHmr &&
    dateOfSaleDiff <= maxDateOfMachineSaleByOEMToEndCustomer &&
    dateOfInvoiceDiff <= maxDateOfSimpsonInvoiceToOEM
  ) {
    underWarranty = true;
  }
  return {
    underWarranty,
    serialNumber: engineDetails.engineSerialNumber,
    invoiceNumber: engineDetails.invoiceNumber,
    hours: engineHmr,
    listNumber: engineDetails.listNo,
    egDetails: {
      sno: engineDetails.engineSerialNumber,
      listNo: engineDetails.listNo,
      invoiceNumber: engineDetails.invoiceNumber,
      invoiceDate: engineDetails.invoiceDate,
      plant: engineDetails.organizationName,
    },
    dateOfSale: {
      cur: dateOfSaleDiff,
      allowed: maxDateOfMachineSaleByOEMToEndCustomer,
      valid: dateOfSaleDiff <= maxDateOfMachineSaleByOEMToEndCustomer,
    },
    hmr: {
      cur: engineHmr,
      allowed: maxHmr,
      valid: engineHmr <= maxHmr,
    },
    dateOfInvoice: {
      cur: dateOfInvoiceDiff,
      allowed: maxDateOfSimpsonInvoiceToOEM,
      valid: dateOfInvoiceDiff <= maxDateOfSimpsonInvoiceToOEM,
    },
    oemName: oem.name,
  };
};

